        self.assertEqual(checkout([{'price':'1.005','qty':3}],0.5),{'subtotal':'3.03','shipping':'5.63','total':'8.63'})
        self.assertEqual(checkout([{'price':'1.005','qty':3}],0.5,express=True),{'subtotal':'3.03','shipping':'11.25','total':'14.28'})
